constexpr std::array<std::uint32_t, 256> makeCrcTable()
{
    std::array<std::uint32_t, 256> table{};
    for (std::uint32_t i{ 0 }; i < 256; ++i)
    {
        std::uint32_t c{ i };
        for (int k{ 0 }; k < 8; ++k)
            c = (c & 1) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
        table[i] = c;
    }
    return table;
}

constexpr auto crcTable{ makeCrcTable() };

